import{_ as r,c as i,o,ah as a}from"./chunks/framework.Ch_PcVtW.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART3/7/0_context_summary.md","filePath":"scripts/output/PART3/7/0_context_summary.md"}'),l={name:"scripts/output/PART3/7/0_context_summary.md"};function s(e,t,n,_,c,u){return o(),i("div",null,[...t[0]||(t[0]=[a('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕SKY-HI参与策划的新音乐节目《Apartment B》展开，介绍节目以公寓为舞台，邀请BMSG艺人及不同领域的歌手、制作人、舞者，通过深度音乐对谈与现场演出，呈现音乐本身的魅力。SKY-HI强调，节目并非追逐即时收视数字的表演集合，而是希望打造真正尊重音乐、鼓励交流与创作自由的内容。他以美国NPR的《tiny desk concerts》为参照，期待节目凭借真实、优质且具有独特性的音乐体验自然扩大影响力。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>SKY-HI</strong>：统一译为“SKY-HI”，不要擅自改译为日高光启；根据上下文保留其CEO、制作人、rapper多重身份。</li><li><strong>BMSG、BE:FIRST、MAZZEL、D.U.N.K.、THE FIRST、MISSIONx2</strong>：均为项目、团体或节目名称，建议保留官方英文及日文标记。</li><li><strong>Apartment B</strong>：标题建议统一为《Apartment B》，日文副标题“アパートメント・ビー”可译作“公寓B”或保留英文读法。</li><li><strong>ALI、LEO、Dos Monos、荘子it、アオイヤマダ、藤井風</strong>：人名和团体名需核对官方中文或常用译法；没有确定译名时保留原文。</li><li><strong>トラックメイカー・MC</strong>：可译为“音乐制作人、MC（说唱歌手）”，避免简单译成“作曲家”。</li><li><strong>オウンドメディア</strong>：译为“自有媒体”，并注意与YouTube平台属性的关系。</li><li><strong>地上波</strong>：译为“日本地面电视”或“日本主流地面频道”，不要直译为“地上波”。</li><li><strong>パフォーマンス番組</strong>：建议译为“表演型音乐节目”，区别于“真正以音乐为核心的节目”。</li><li><strong>数字、エビデンス</strong>：此处“数字”指收视率等即时指标；“エビデンス”指数据依据或实证，不宜译成泛泛的“证据”。</li><li><strong>语气</strong>：整体兼具管理者的分析性与艺术家的热情，不能过度书面化；“ああ、やられたっ！！”“(笑)”需保留惊讶、幽默和亲近感。</li><li>原文“集まっ番組制作チーム”疑似漏字，翻译时按“聚集起来的节目制作团队”理解，并建议后续校对原稿。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>准确区分节目介绍部分的客观第三人称叙述，与SKY-HI第一人称访谈部分。</li><li>将“本当の意味での音楽番組”“音楽そのものの本質的な楽しさ”等核心表达稳定译为“真正意义上的音乐节目”“音乐本身最本质的乐趣”，形成主题回环。</li><li>“即時的な数字に逃げない”不要直译为“逃离即时数字”，可译为“不逃避到即时数据/短期指标中”。</li><li>保留“音乐对谈、歌唱、现场演出、舞蹈收敛”等节目结构信息，突出其重视音乐表达而非单纯视觉表演。</li><li>“良いものはキャッチー”应译得自然有力，如“真正好的东西本身就具有传播力”，避免将“catchy”机械译为“朗朗上口”。</li><li>适度保留口语停顿、感叹和“さん”“くん”体现的人际亲近感，但不要影响中文出版物的流畅度。</li><li>对《tiny desk concerts》可保留英文，并首次出现时加注“美国公共广播NPR推出的音乐内容系列”。</li></ul>',6)])])}const d=r(l,[["render",s]]);export{m as __pageData,d as default};
